// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor1, uint256 amount1, address actor2, uint256 amount2) public {
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        amount1 = bound(amount1, 0, 10 ether);
        amount2 = bound(amount2, 0, 10 ether);

        vm.deal(actor1, amount1);
        vm.prank(actor1);
        c.Put{value: amount1}(0);

        bool secondOk;
        vm.deal(actor2, amount2);
        vm.prank(actor2);
        try c.Put{value: amount2}(0) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        assertTrue(secondOk, "a completed Put must not lock the contract against further Puts");
    }
}
